-- Lahore and its 68 districts. Together the outlines cover the whole of Lahore District
-- (OpenStreetMap relation 16117666, 1,801 km², including the land outside the Ring Road)
-- with no gaps or overlaps, and each district is one connected piece.
--
-- Districts are built around the neighbourhoods they are named after: Zameen.com society and
-- DHA phase outlines, OpenStreetMap neighbourhood and campus outlines (ODbL), and 2017 union
-- councils (Alhasan Systems via HDX, CC0) for the remaining land. Busy commercial hubs were
-- checked against OpenStreetMap, Zameen and Google venue clusters so each hub sits in one
-- recognisable district. Generated data (2026-11-20); replaceable like the rest of the catalog.
--
-- Run before lahore_osm_places.sql, which places each OSM place in the district containing it.
ON CONFLICT (id) DO UPDATE SET parent_id=EXCLUDED.parent_id, name=EXCLUDED.name,
    slug=EXCLUDED.slug, type=EXCLUDED.type, sort_order=EXCLUDED.sort_order;

-- Popular districts first, then the rest alphabetically. Districts that existed in the earlier
-- catalog keep their IDs.

ON CONFLICT (id) DO UPDATE SET parent_id=EXCLUDED.parent_id, name=EXCLUDED.name,
    slug=EXCLUDED.slug, type=EXCLUDED.type, sort_order=EXCLUDED.sort_order, boundary=EXCLUDED.boundary;

-- Places already in the database move to the district that now contains them.
UPDATE places SET area_id = districts.id
FROM areas AS districts
WHERE districts.parent_id = '00000000-0000-4000-8000-000000000101'
    AND ST_Contains(districts.boundary, places.location)
    AND places.area_id IS DISTINCT FROM districts.id;

-- Jail Road & Upper Mall from the earlier catalog is now part of Mozang & Mall Road.
DELETE FROM areas
WHERE id = '00000000-0000-4000-8000-000000000214'
    AND NOT EXISTS (SELECT 1 FROM places WHERE places.area_id = areas.id)
    AND NOT EXISTS (SELECT 1 FROM area_scene_sources WHERE area_scene_sources.area_id = areas.id);
